"""Attachments (BR-073/074, BR-100/101, AC-ATT-*, AC-SEC-015..017).

* Server-side size limit (5 MB per file) enforced while streaming, before persistence.
* Content inspection: magic bytes + structural checks (Pillow verification for images, PDF header/trailer).
* Extension and detected type must agree; browser MIME type is ignored.
* Storage names are random, generated by the application; user filenames are metadata only.
"""
from __future__ import annotations

import hashlib
import io
import os
import re
import unicodedata
import uuid
from pathlib import Path

from PIL import Image
from sqlalchemy import func, select
from sqlalchemy.orm import Session

from .. import audit
from ..errors import AppError, conflict, forbidden, not_found, validation
from ..models import Attachment, FiscalYear, Fundraiser, RegisterTransaction, TransactionAllocation, utcnow
from .common import get_scoped
from .register import is_closed_protected

MAX_BYTES = 5 * 1024 * 1024
CHUNK = 64 * 1024
EXT_TYPES = {".pdf": "application/pdf", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png"}
OWNER_TYPES = ("fiscal_year", "transaction", "allocation", "fundraiser")
OWNER_COLUMN = {"fiscal_year": "fiscal_year_id", "transaction": "transaction_id", "allocation": "allocation_id",
                "fundraiser": "fundraiser_id"}


def sanitize_filename(name: str | None) -> str:
    """Filename is metadata only; strip any path component (both separators), control chars and length."""
    name = unicodedata.normalize("NFC", name or "")
    name = re.split(r"[\\/]", name)[-1]
    name = "".join(c for c in name if unicodedata.category(c)[0] != "C").strip().strip(".")
    return (name or "attachment")[:200]


def detect_type(data: bytes) -> str | None:
    if data.startswith(b"%PDF-"):
        tail = data[-2048:]
        if b"%%EOF" not in tail:
            return None
        return "application/pdf"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        fmt = "PNG"
        mime = "image/png"
    elif data.startswith(b"\xff\xd8\xff"):
        fmt = "JPEG"
        mime = "image/jpeg"
    else:
        return None
    try:
        with Image.open(io.BytesIO(data)) as im:
            if im.format != fmt:
                return None
            im.verify()
    except Exception:
        return None
    return mime


async def read_limited(upload) -> bytes:
    buf = bytearray()
    while True:
        chunk = await upload.read(CHUNK)
        if not chunk:
            break
        buf.extend(chunk)
        if len(buf) > MAX_BYTES:
            raise AppError(413, "FILE_TOO_LARGE", "Attachments may not exceed 5 MB per file.")
    return bytes(buf)


def _resolve_owner(db: Session, ctx, owner_type: str, owner_id: int):
    if owner_type == "fiscal_year":
        fy = get_scoped(db, FiscalYear, owner_id, ctx, "Fiscal Year")
        return fy, None, fy
    if owner_type == "transaction":
        t = get_scoped(db, RegisterTransaction, owner_id, ctx, "Transaction")
        return t, t, None
    if owner_type == "allocation":
        a = db.get(TransactionAllocation, owner_id) if isinstance(owner_id, int) else None
        if a is None or a.transaction.workspace_id != ctx.workspace_id or a.removed_at is not None:
            raise not_found("Allocation")
        return a, a.transaction, None
    if owner_type == "fundraiser":  # v1.6.1 CR-034: fundraiser documents (module must be on)
        from . import fundraisers as fsvc
        fsvc.require_module(db, ctx)
        ctx.require("fundraiser.view")
        return get_scoped(db, Fundraiser, owner_id, ctx, "Fundraiser"), None, None
    raise validation("Unsupported owner type.", "owner_type")


def check_manage(ctx, owner_type: str) -> None:
    ctx.require({"fiscal_year": "fiscal_year.manage", "fundraiser": "fundraiser.lines"}.get(owner_type, "transaction.manage"))


def _fundraiser_open(db: Session, ctx, f: Fundraiser) -> None:
    from . import fundraisers as fsvc
    fsvc._require_open(db, ctx, f)


FY_DOCUMENT_TYPES = ("APPROVAL", "AUDIT_SIGNOFF", "UNSPECIFIED")  # v1.3 CR-007 (user-selectable)
CLOSE_REPORT = "CLOSE_REPORT"  # v1.3 CR-008: system-generated at closing


def _write_file(settings, data: bytes) -> tuple[str, Path]:
    key = uuid.uuid4().hex
    base = settings.attachments_dir.resolve()
    shard = base / key[:2]
    shard.mkdir(parents=True, exist_ok=True)
    path = (shard / (key + ".bin")).resolve()
    if base not in path.parents:  # defence in depth; key is generated hex
        raise AppError(500, "INTEGRITY", "Invalid storage path.")
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0), 0o600)
    with os.fdopen(fd, "wb") as fh:
        fh.write(data)
    return key, path


# ------------------------------------------------------------------ 2.4.0 (#425): identical content is stored once
def stored_match(db: Session, workspace_id: int, settings, data: bytes, sha: str | None = None) -> Attachment | None:
    """An attachment of this workspace whose stored file has exactly these bytes (SHA-256 first, then a byte-for-byte
    comparison), else None. Removed attachments count too: their files are kept for history."""
    sha = sha or hashlib.sha256(data).hexdigest()
    seen: set[str] = set()
    for a in db.scalars(select(Attachment).where(Attachment.workspace_id == workspace_id, Attachment.sha256 == sha,
                                                 Attachment.size_bytes == len(data)).order_by(Attachment.id)):
        if a.storage_key in seen:
            continue
        seen.add(a.storage_key)
        try:
            if path_for(settings, a).read_bytes() == data:
                return a
        except (OSError, AppError):
            continue
    return None


def new_record(db: Session, ctx, settings, data: bytes, **fields) -> tuple[Attachment, Path | None]:
    """Creates an attachment record for these (already validated) bytes and its ATTACHMENT_ADDED audit event, inside
    the caller's database transaction. An identical stored file in the workspace is linked instead of writing a new
    one (the audit event notes the link). Returns the record and the path of a newly written file (None when linked)
    so the caller can remove it if the transaction fails - a linked file is never removed (#425)."""
    sha = hashlib.sha256(data).hexdigest()
    match = stored_match(db, ctx.workspace_id, settings, data, sha)
    if match is not None:
        key, path = match.storage_key, None
    else:
        key, path = _write_file(settings, data)
    try:
        att = Attachment(workspace_id=ctx.workspace_id, storage_key=key, size_bytes=len(data), sha256=sha,
                         uploaded_by_user_id=ctx.user.id, active=True, **fields)
        db.add(att)
        db.flush()
        after = snapshot(att)
        if match is not None:
            after["shares_file_with_attachment_id"] = match.id
        audit.record(db, ctx, "ATTACHMENT_ADDED", "attachment", att.id, None, after)
    except Exception:
        discard_new_file(path)       # the caller never got the path; the caller rolls the transaction back
        raise
    return att, path


def discard_new_file(path: Path | None) -> None:
    """After a failed save: removes a file this request wrote (never a linked, shared one)."""
    if path is not None:
        try:
            path.unlink()
        except OSError:
            pass


def merge_duplicate_files(session_factory, settings) -> dict:
    """2.4.0 (#425): links attachment records whose stored files have identical content to one file and removes the
    extra copies. Runs at start-up after the migrations (an upgrade from 2.3 and earlier: after the installer's
    pre-upgrade backup) and after a restore; with nothing to merge it is one query. Each file is read and its SHA-256
    checked against the recorded value first - a file that is missing or no longer matches is left alone and
    reported (logged, and counted in the audit event). Only files no record references any more are removed, after
    the database change is committed. Returns counts."""
    import logging
    from types import SimpleNamespace
    log = logging.getLogger("fmpoc.attachments")
    result = {"groups": 0, "records_relinked": 0, "files_removed": 0, "bytes_freed": 0, "files_not_verified": 0}
    with session_factory() as db:
        groups = db.execute(select(Attachment.workspace_id, Attachment.sha256)
                            .group_by(Attachment.workspace_id, Attachment.sha256)
                            .having(func.count(func.distinct(Attachment.storage_key)) > 1)).all()
        if not groups:
            return result
        removable: list[Path] = []
        per_ws: dict[int, dict] = {}
        for ws_id, sha in groups:
            rows = list(db.scalars(select(Attachment).where(Attachment.workspace_id == ws_id,
                                                            Attachment.sha256 == sha).order_by(Attachment.id)))
            keeper, keeper_data = None, None
            for key in dict.fromkeys(a.storage_key for a in rows):     # oldest first
                first = next(a for a in rows if a.storage_key == key)
                try:
                    data = path_for(settings, first).read_bytes()
                except (OSError, AppError):
                    data = None
                if data is None or hashlib.sha256(data).hexdigest() != sha:
                    result["files_not_verified"] += 1
                    log.warning("Attachment %s: stored file missing or its SHA-256 differs from the recorded one; "
                                "left as it is (not merged).", first.id)
                    continue
                if keeper is None:
                    keeper, keeper_data = key, data
                    continue
                if data != keeper_data:          # same hash, different bytes: never merged
                    result["files_not_verified"] += 1
                    continue
                extra = path_for(settings, first)        # before the rows move to the kept file
                for a in rows:
                    if a.storage_key == key:
                        a.storage_key = keeper
                        result["records_relinked"] += 1
                        w = per_ws.setdefault(ws_id, {"records_relinked": 0, "files_removed": 0, "bytes_freed": 0})
                        w["records_relinked"] += 1
                removable.append(extra)
                per_ws[ws_id]["files_removed"] += 1
                per_ws[ws_id]["bytes_freed"] += len(data)
                result["bytes_freed"] += len(data)
            result["groups"] += 1
        db.flush()
        for ws_id, counts in per_ws.items():
            ctx = SimpleNamespace(workspace_id=ws_id, user=None, correlation_id=None, ip=None)
            audit.record(db, ctx, "ATTACHMENT_FILES_MERGED", "workspace", ws_id, None,
                         {**counts, "files_not_verified": result["files_not_verified"],
                          "note": "Identical attachment files are now stored once; every attachment is unchanged."},
                         )
        db.commit()
    for p in removable:
        try:
            p.unlink()
            result["files_removed"] += 1
        except OSError:
            pass
    log.info("Attachment files merged: %s", result)
    return result


def store_system_fy_document(db: Session, ctx, settings, fy: FiscalYear, filename: str, data: bytes,
                             document_type: str) -> tuple[Attachment, Path | None]:
    """Stores an application-generated PDF (e.g. the Close report) as a permanent Fiscal Year attachment. Runs inside
    the caller's database transaction; the caller commits (or discards the returned new file on failure)."""
    return new_record(db, ctx, settings, data, original_filename=sanitize_filename(filename),
                      mime_type="application/pdf", fiscal_year_id=fy.id, document_type=document_type,
                      system_generated=True, sort_order=_next_position(db, "fiscal_year", fy.id))


def store(db: Session, ctx, settings, owner_type: str, owner_id: int, filename: str | None, data: bytes,
          document_type: str | None = None, attach_anyway: bool = False) -> Attachment:
    check_manage(ctx, owner_type)
    owner, _txn, _fy = _resolve_owner(db, ctx, owner_type, owner_id)
    if owner_type == "fundraiser":
        _fundraiser_open(db, ctx, owner)
    if owner_type == "fiscal_year":
        document_type = document_type or "UNSPECIFIED"
        if document_type not in FY_DOCUMENT_TYPES:
            raise validation("Unknown Fiscal Year document type.", "document_type")
    elif document_type is not None:
        raise validation("document_type applies to Fiscal Year attachments only.", "document_type")
    if len(data) == 0:
        raise validation("The file is empty.", "file")
    if len(data) > MAX_BYTES:
        raise AppError(413, "FILE_TOO_LARGE", "Attachments may not exceed 5 MB per file.")
    clean = sanitize_filename(filename)
    ext = os.path.splitext(clean)[1].lower()
    if ext not in EXT_TYPES:
        raise AppError(415, "UNSUPPORTED_TYPE", "Only PDF, JPG/JPEG and PNG files are permitted.")
    detected = detect_type(data)
    if detected is None or detected != EXT_TYPES[ext]:
        raise AppError(415, "UNSUPPORTED_TYPE",
                       "The file content is not a valid PDF, JPEG or PNG matching its extension.")
    # #425: the same file already attached to this record - the user decides (checked after validation, server-side)
    if not attach_anyway:
        col = getattr(Attachment, OWNER_COLUMN[owner_type])
        same = db.scalar(select(Attachment).where(col == owner.id, Attachment.active.is_(True),
                                                  Attachment.sha256 == hashlib.sha256(data).hexdigest())
                         .order_by(Attachment.id))
        if same is not None:
            raise AppError(409, "DUPLICATE_ON_RECORD",
                           f"This file is already attached here as \"{same.original_filename}\". "
                           "Attach it again anyway?")
    path = None
    try:
        att, path = new_record(db, ctx, settings, data, original_filename=clean, mime_type=detected,
                               document_type=document_type, sort_order=_next_position(db, owner_type, owner.id),
                               **{OWNER_COLUMN[owner_type]: owner.id})
        # v1.2: documentation now exists, so a "no attachment will be provided" marker no longer applies
        if owner_type == "allocation" and owner.no_attachment:
            owner.no_attachment, owner.no_attachment_reason = False, None
            owner.no_attachment_set_at = owner.no_attachment_set_by_user_id = None
            audit.record(db, ctx, "ALLOCATION_NO_ATTACHMENT_CLEARED", "transaction_allocation", owner.id,
                         {"no_attachment": True}, {"no_attachment": False, "attachment_id": att.id})
        # v1.3 CR-007: an approval document replaces the "no approval document" mark
        if owner_type == "fiscal_year" and document_type == "APPROVAL" and owner.approval_no_attachment:
            owner.approval_no_attachment, owner.approval_no_attachment_reason = False, None
            owner.approval_no_attachment_set_at = owner.approval_no_attachment_set_by_user_id = None
            audit.record(db, ctx, "FY_APPROVAL_NO_ATTACHMENT_CLEARED", "fiscal_year", owner.id,
                         {"approval_no_attachment": True}, {"approval_no_attachment": False, "attachment_id": att.id})
        txn = _txn if owner_type == "transaction" else None
        if txn is not None and txn.no_attachment:
            txn.no_attachment, txn.no_attachment_reason = False, None
            txn.no_attachment_set_at = txn.no_attachment_set_by_user_id = None
            audit.record(db, ctx, "TRANSACTION_NO_ATTACHMENT_CLEARED", "register_transaction", txn.id,
                         {"no_attachment": True}, {"no_attachment": False, "attachment_id": att.id})
        db.commit()
    except Exception:
        db.rollback()
        discard_new_file(path)
        raise
    return att


# 2.1.0 (#259): the one order every list, report and download uses - the saved order, else upload order
DISPLAY_ORDER = (func.coalesce(Attachment.sort_order, Attachment.id), Attachment.id)
REORDERABLE_FY_TYPES = ("UNSPECIFIED",)   # Approval and Audit signoff keep their fixed place
AUDIT_OBJECT = {"transaction": "register_transaction", "allocation": "transaction_allocation",
                "fiscal_year": "fiscal_year", "fundraiser": "fundraiser"}


def _next_position(db: Session, owner_type: str, owner_id: int) -> int | None:
    """New uploads go to the end once an owner's attachments have been reordered (None = upload order is enough)."""
    col = getattr(Attachment, OWNER_COLUMN[owner_type])
    if db.scalar(select(func.count(Attachment.id)).where(col == owner_id, Attachment.sort_order.is_not(None))) == 0:
        return None
    return (db.scalar(select(func.max(func.coalesce(Attachment.sort_order, Attachment.id))).where(col == owner_id))
            or 0) + 1


def reorder(db: Session, ctx, owner_type: str, owner_id: int, ids: list[int]) -> list[Attachment]:
    """2.1.0 (#259): save the order of an owner's active attachments (all of them; for a Fiscal Year its Unspecified
    documents). Same rights as adding attachments there; not in a Closed Fiscal Year (BR-012), not on a deleted
    transaction; allowed on a VOID one while its year is open (BR-070). Audited with the order before and after.
    Ordering is a documentation change, never a financial edit (no cleared-transaction confirmation)."""
    check_manage(ctx, owner_type)
    owner, txn, _fy = _resolve_owner(db, ctx, owner_type, owner_id)
    if owner_type == "fiscal_year":
        if owner.status == "CLOSED":
            raise conflict("FISCAL_YEAR_CLOSED", "Closed Fiscal Year documentation cannot be reordered.")
    elif owner_type == "fundraiser":
        _fundraiser_open(db, ctx, owner)
    else:
        if txn.status == "DELETED":
            raise conflict("TRANSACTION_DELETED", "Attachments of a deleted transaction cannot be reordered.")
        if is_closed_protected(db, txn):
            raise conflict("FISCAL_YEAR_CLOSED", "Attachments on Closed Fiscal Year transactions cannot be reordered.")
    col = getattr(Attachment, OWNER_COLUMN[owner_type])
    q = select(Attachment).where(col == owner.id, Attachment.active.is_(True)).order_by(*DISPLAY_ORDER)
    current = list(db.scalars(q))
    if owner_type == "fiscal_year":
        current = [a for a in current if (a.document_type or "UNSPECIFIED") in REORDERABLE_FY_TYPES]
    if len(ids) != len(set(ids)) or sorted(ids) != sorted(a.id for a in current):
        raise validation("List every attachment shown here exactly once, in the new order.", "attachment_ids")
    before = [{"id": a.id, "name": a.original_filename} for a in current]
    if [a.id for a in current] == ids:
        return current
    by_id = {a.id: a for a in current}
    # positions after everything the owner has, so they never tie with an attachment still in upload order
    base = db.scalar(select(func.max(func.coalesce(Attachment.sort_order, Attachment.id))).where(col == owner.id)) or 0
    for pos, aid in enumerate(ids, start=1):
        by_id[aid].sort_order = base + pos
    db.flush()
    after = [{"id": i, "name": by_id[i].original_filename} for i in ids]
    audit.record(db, ctx, "ATTACHMENTS_REORDERED", AUDIT_OBJECT[owner_type], owner.id,
                 {"attachment_order": before}, {"attachment_order": after})
    return [by_id[i] for i in ids]


def snapshot(a: Attachment) -> dict:
    return {"id": a.id, "original_filename": a.original_filename, "mime_type": a.mime_type, "size_bytes": a.size_bytes,
            "sha256": a.sha256, "fiscal_year_id": a.fiscal_year_id, "transaction_id": a.transaction_id,
            "allocation_id": a.allocation_id, "fundraiser_id": a.fundraiser_id, "active": a.active,
            "document_type": a.document_type,
            "system_generated": bool(a.system_generated)}  # sort_order is not snapshotted: reorders have their own event


def out(a: Attachment) -> dict:
    return {**snapshot(a), "uploaded_at": a.uploaded_at.isoformat() + "Z", "uploaded_by_user_id": a.uploaded_by_user_id,
            "removed_at": a.removed_at.isoformat() + "Z" if a.removed_at else None,
            "content_url": f"/api/attachments/{a.id}/content"}


def list_for(db: Session, ctx, owner_type: str, owner_id: int, include_removed: bool) -> list[Attachment]:
    owner, _t, _f = _resolve_owner(db, ctx, owner_type, owner_id)
    col = getattr(Attachment, OWNER_COLUMN[owner_type])
    # removed ones (history) after the active ones, each in display order (#259)
    q = select(Attachment).where(col == owner.id).order_by(Attachment.active.desc(), *DISPLAY_ORDER)
    if not include_removed:
        q = q.where(Attachment.active.is_(True))
    return list(db.scalars(q))


def get(db: Session, ctx, att_id: int) -> Attachment:
    a = get_scoped(db, Attachment, att_id, ctx, "Attachment")
    if a.fundraiser_id:  # v1.6.1 CR-034: fundraiser documents follow the module switch and its viewers
        from . import fundraisers as fsvc
        fsvc.require_module(db, ctx)
        ctx.require("fundraiser.view")
    return a


def path_for(settings, a: Attachment) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", a.storage_key):
        raise AppError(500, "INTEGRITY", "Invalid storage key.")
    return settings.attachments_dir / a.storage_key[:2] / (a.storage_key + ".bin")


def remove(db: Session, ctx, a: Attachment) -> Attachment:
    if not a.active:
        raise conflict("INVALID_STATE", "Attachment already removed.")
    if a.system_generated:
        raise conflict("SYSTEM_GENERATED", "System-generated documents (e.g. the Close report) cannot be removed.")
    if a.fiscal_year_id:
        ctx.require("fiscal_year.manage")
        fy = db.get(FiscalYear, a.fiscal_year_id)
        if fy.status == "CLOSED":
            raise conflict("FISCAL_YEAR_CLOSED", "Closed Fiscal Year documentation cannot be removed.")
    elif a.fundraiser_id:
        ctx.require("fundraiser.lines")
        _fundraiser_open(db, ctx, db.get(Fundraiser, a.fundraiser_id))
    else:
        ctx.require("transaction.manage")
        t = db.get(RegisterTransaction, a.transaction_id) if a.transaction_id else db.get(TransactionAllocation, a.allocation_id).transaction
        if t.status in ("VOID", "DELETED"):
            raise conflict("TRANSACTION_VOID", "Existing attachments on a VOID or deleted transaction cannot be removed.")
        if is_closed_protected(db, t):
            raise conflict("FISCAL_YEAR_CLOSED", "Attachments on Closed Fiscal Year transactions cannot be removed.")
    before = snapshot(a)
    a.active = False
    a.removed_at = utcnow()
    a.removed_by_user_id = ctx.user.id
    db.flush()
    audit.record(db, ctx, "ATTACHMENT_REMOVED", "attachment", a.id, before, snapshot(a))
    return a


def set_document_type(db: Session, ctx, a: Attachment, document_type: str) -> Attachment:
    """v1.3 CR-007: re-label a Fiscal Year attachment (e.g. mark an earlier upload as the Audit Signoff)."""
    ctx.require("fiscal_year.manage")
    if a.fiscal_year_id is None:
        raise validation("Only Fiscal Year attachments have a document type.", "document_type")
    if document_type not in FY_DOCUMENT_TYPES:
        raise validation("Unknown Fiscal Year document type.", "document_type")
    if not a.active:
        raise conflict("INVALID_STATE", "The attachment has been removed.")
    if a.system_generated:
        raise conflict("SYSTEM_GENERATED", "System-generated documents cannot be re-labelled.")
    fy = db.get(FiscalYear, a.fiscal_year_id)
    if fy.status == "CLOSED":
        raise conflict("FISCAL_YEAR_CLOSED", "Closed Fiscal Year documentation cannot be changed.")
    if a.document_type == document_type:
        raise conflict("NO_CHANGE", "The document type is unchanged.")
    before = snapshot(a)
    a.document_type = document_type
    if document_type == "APPROVAL" and fy.approval_no_attachment:
        fy.approval_no_attachment, fy.approval_no_attachment_reason = False, None
        fy.approval_no_attachment_set_at = fy.approval_no_attachment_set_by_user_id = None
        audit.record(db, ctx, "FY_APPROVAL_NO_ATTACHMENT_CLEARED", "fiscal_year", fy.id,
                     {"approval_no_attachment": True}, {"approval_no_attachment": False, "attachment_id": a.id})
    db.flush()
    audit.record(db, ctx, "ATTACHMENT_TYPE_CHANGED", "attachment", a.id, before, snapshot(a))
    return a


__all__ = ["forbidden"]
